import pathlib
m = {"approach.md": "## Approach", "tasks.md": "## Tasks", "test-plan.md": "## Test Cases"}
for d in ("phase-boundary-confirmation", "service-mediated-corpus-ingest"):
    for fn, sec in m.items():
        p = pathlib.Path(d) / fn
        lines = p.read_text(encoding="utf-8").splitlines()
        if any(l.strip().lstrip("#").strip().lower() == sec.lstrip("#").strip().lower() for l in lines if l.startswith("#")):
            continue
        lines.insert(1, f"\n{sec}")
        p.write_text("\n".join(lines) + "\n", encoding="utf-8")
        print("added", sec, "->", p)
PY

